#[test]
fn notification_observes_the_already_published_snapshot() -> Result<(), Box<dyn std::error::Error>> {
    let (publisher, receiver) = ChainEventPublisher::new(7, initial(7));
    let hash = Hash256::from_le_bytes(&[0x42; 32]);
    let emitted = publisher.record(HintKind::Connected, 42, hash);
    let received = receiver.try_recv()?;
    assert_eq!(received, emitted);
    assert_eq!(
        publisher.snapshot(),
        ChainSnapshot {
            epoch: 7,
            sequence: 1,
            tip_hash: hash,
            tip_height: 42,
        }
    );
    Ok(())
}

#[test]
fn saturated_hints_do_not_prevent_snapshot_progress() -> Result<(), Box<dyn std::error::Error>> {
    let (publisher, receiver) = ChainEventPublisher::new(9, initial(9));
    let last_height = u32::try_from(CHAIN_HINT_CHANNEL_LIMIT)? + 1;
    let hash = Hash256::from_le_bytes(&[0x24; 32]);
    for height in 1..=last_height {
        publisher.record(HintKind::Connected, height, hash);
    }
    assert_eq!(receiver.len(), CHAIN_HINT_CHANNEL_LIMIT);
    assert_eq!(
        publisher.snapshot(),
        ChainSnapshot {
            epoch: 9,
            sequence: u64::from(last_height),
            tip_hash: hash,
            tip_height: last_height,
        }
    );
    Ok(())
}

#[test]
fn a_detached_consumer_cannot_veto_a_committed_transition() {
    let (publisher, receiver) = ChainEventPublisher::new(11, initial(11));
    drop(receiver);
    let hash = Hash256::from_le_bytes(&[0x31; 32]);
    let hint = publisher.record(HintKind::Disconnected, 31, hash);
    assert_eq!(hint.epoch, 11);
    assert_eq!(hint.sequence, 1);
    assert_eq!(publisher.snapshot().tip_hash, hash);
    assert_eq!(publisher.snapshot().tip_height, 31);
    assert_eq!(publisher.snapshot().sequence, hint.sequence);
}
